  -H "Content-Type: application/json" \
  -d '{
    "query": "query { team(id: \"t-plt\") { id name cycles { nodes { id number startDate dueDate } } currentCycle { id number startDate dueDate } nextCycle { id number startDate dueDate } } }"
  }'

